  for cond in ('no_traj','gt_action'):
   P=np.stack([v[f'{i}_{h}_{cond}'] for i in ids]).astype('f8');ratio=(np.linalg.norm(P,axis=2)/np.maximum(np.linalg.norm(Y,axis=2),1e-12)).mean(1);tokens.append(dict(subset=subset,h=h,condition=cond,mean_per_token_norm_ratio=a.estimate(ratio,w0,w)))
